import React, { useState, useEffect, useRef } from 'react';
import { Upload, FileText, X, AlertCircle, Trash2, Send, Bot, Users } from 'lucide-react';
import api from '../config/api';
import { useAuth } from '../context/AuthContext';

const ChatTab = ({ projectId, messages, user, onRefresh, project }) => {
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const messagesEndRef = useRef(null);
  
  // Document chat states
  const [chatMode, setChatMode] = useState('team'); // 'team' or 'ai'
  const [file, setFile] = useState(null);
  const [uploadStatus, setUploadStatus] = useState('');
  const [uploading, setUploading] = useState(false);
  const [aiMessages, setAiMessages] = useState([]);
  const [aiQuestion, setAiQuestion] = useState('');
  const [aiLoading, setAiLoading] = useState(false);
  const [error, setError] = useState('');
  const [uploadedDocuments, setUploadedDocuments] = useState([]);

  // Check if current user is the owner
  const isOwner = user && project && project.owner && user.id === project.owner.id;

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, aiMessages]);

  useEffect(() => {
    if (chatMode === 'ai') {
      fetchAiChatHistory();
      fetchUploadedDocuments();
    }
  }, [chatMode, projectId]);

  // Fetch AI chat history
  const fetchAiChatHistory = async () => {
    try {
      const response = await api.get(`/api/projects/${projectId}/chat-history`);
      setAiMessages(response.data || []);
    } catch (err) {
      console.error('Error fetching AI chat history:', err);
    }
  };

  // Fetch uploaded documents
  const fetchUploadedDocuments = async () => {
    try {
      const response = await api.get(`/api/projects/${projectId}/documents`);
      setUploadedDocuments(response.data || []);
    } catch (err) {
      console.error('Error fetching documents:', err);
    }
  };

  // Handle file selection
  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setFile(selectedFile);
      setUploadStatus('');
      setError('');
    }
  };

  // Upload document
  const handleUpload = async () => {
    if (!file) {
      setError('Please select a file first');
      return;
    }

    setUploading(true);
    setError('');
    setUploadStatus('');

    try {
      const formData = new FormData();
      formData.append('fileToUpload', file);
      formData.append('projectId', projectId);

      const response = await api.post(`/api/projects/${projectId}/upload-document`, formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      if (response.status === 200) {
        setUploadStatus('Document uploaded successfully!');
        const fileName = file.name;
        setFile(null);
        
        // Add system message
        const systemMessage = {
          type: 'system',
          text: `Document "${fileName}" has been uploaded and processed. You can now ask questions about it.`,
          timestamp: new Date().toISOString(),
        };
        setAiMessages(prev => [...prev, systemMessage]);
        
        // Refresh documents list
        fetchUploadedDocuments();
      }
    } catch (err) {
      setError('Failed to upload document. Please try again.');
      console.error('Upload error:', err);
    } finally {
      setUploading(false);
    }
  };

  // Remove uploaded file selection
  const handleRemoveFile = () => {
    setFile(null);
    setUploadStatus('');
    setError('');
  };

  // Delete uploaded document
  const handleDeleteDocument = async (documentId) => {
    if (!window.confirm('Are you sure you want to delete this document?')) {
      return;
    }

    try {
      await api.delete(`/api/projects/${projectId}/documents/${documentId}`);
      setUploadedDocuments(prev => prev.filter(doc => doc.id !== documentId));
      
      const systemMessage = {
        type: 'system',
        text: 'Document has been deleted.',
        timestamp: new Date().toISOString(),
      };
      setAiMessages(prev => [...prev, systemMessage]);
    } catch (err) {
      console.error('Error deleting document:', err);
      setError('Failed to delete document.');
    }
  };

  // Ask AI question
  const handleAskAiQuestion = async () => {
    if (!aiQuestion.trim()) {
      return;
    }

    const userMessage = {
      type: 'user',
      text: aiQuestion,
      userId: user?.id,
      userName: user?.fullName || 'You',
      timestamp: new Date().toISOString(),
    };
    
    setAiMessages(prev => [...prev, userMessage]);
    setAiLoading(true);
    setError('');
    const currentQuestion = aiQuestion;
    setAiQuestion('');

    try {
      const response = await api.post(`/api/projects/${projectId}/chat`, {
        question: currentQuestion,
        userId: user?.id,
      });

      const aiMessage = {
        type: 'ai',
        text: response.data.answer || response.data.response || 'No response received',
        timestamp: new Date().toISOString(),
      };
      
      setAiMessages(prev => [...prev, aiMessage]);
    } catch (err) {
      setError('Failed to get answer. Please try again.');
      console.error('AI Chat error:', err);
      
      const errorMessage = {
        type: 'error',
        text: 'Sorry, I encountered an error. Please try again.',
        timestamp: new Date().toISOString(),
      };
      setAiMessages(prev => [...prev, errorMessage]);
    } finally {
      setAiLoading(false);
    }
  };

  // Team chat - send message
  const handleSendMessage = async (e) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    setLoading(true);
    try {
      await api.post('/api/messages/send', {
        senderId: user.id,
        projectId: projectId,
        content: newMessage
      });
      setNewMessage('');
      onRefresh();
    } catch (err) {
      console.error('Error sending message:', err);
      alert('Failed to send message');
    } finally {
      setLoading(false);
    }
  };

  // Delete all team messages
  const handleDeleteAllMessages = async () => {
    setDeleting(true);
    try {
      await api.delete(`/api/messages/chat/${projectId}`);
      setShowDeleteConfirm(false);
      onRefresh();
      alert('Chat history deleted successfully');
    } catch (err) {
      console.error('Error deleting messages:', err);
      alert(err.response?.data?.message || 'Failed to delete chat history');
    } finally {
      setDeleting(false);
    }
  };

  return (
    <div className="space-y-4">
      {/* Mode Toggle */}
      <div className="flex gap-2 p-1 bg-gray-100 rounded-lg">
        <button
          onClick={() => setChatMode('team')}
          className={`flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-lg font-medium transition ${
            chatMode === 'team'
              ? 'bg-white text-blue-600 shadow-sm'
              : 'text-gray-600 hover:text-gray-900'
          }`}
        >
          <Users size={18} />
          Team Chat
        </button>
        <button
          onClick={() => setChatMode('ai')}
          className={`flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-lg font-medium transition ${
            chatMode === 'ai'
              ? 'bg-white text-purple-600 shadow-sm'
              : 'text-gray-600 hover:text-gray-900'
          }`}
        >
          <Bot size={18} />
          AI Document Chat
        </button>
      </div>

      {/* Team Chat Mode */}
      {chatMode === 'team' && (
        <div className="flex flex-col h-96">
          {/* Header with Delete Button (Only for Owner) */}
          {isOwner && messages.length > 0 && (
            <div className="mb-3 flex justify-between items-center pb-3 border-b">
              <span className="text-sm text-gray-600">
                {messages.length} message{messages.length !== 1 ? 's' : ''}
              </span>
              <button
                onClick={() => setShowDeleteConfirm(true)}
                className="px-3 py-1 bg-red-600 text-white text-sm rounded hover:bg-red-700 transition"
              >
                Clear Chat History
              </button>
            </div>
          )}

          {/* Messages Container */}
          <div className="flex-1 overflow-y-auto space-y-3 mb-4 p-4 bg-gray-50 rounded">
            {messages.map((msg) => (
              <div
                key={msg.id}
                className={`flex ${msg.sender?.id === user.id ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-xs px-4 py-2 rounded-lg ${
                    msg.sender?.id === user.id
                      ? 'bg-blue-600 text-white'
                      : 'bg-white text-gray-900 border border-gray-200'
                  }`}
                >
                  {msg.sender?.id !== user.id && (
                    <div className="text-xs font-semibold mb-1 opacity-75">
                      {msg.sender?.fullName}
                    </div>
                  )}
                  <p className="text-sm">{msg.content}</p>
                  <div className={`text-xs mt-1 ${msg.sender?.id === user.id ? 'text-blue-100' : 'text-gray-500'}`}>
                    {new Date(msg.createdAt).toLocaleTimeString()}
                  </div>
                </div>
              </div>
            ))}
            {messages.length === 0 && (
              <div className="text-center text-gray-500 py-12">
                No messages yet. Start the conversation!
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Message Input */}
          <div className="flex gap-2">
            <input
              type="text"
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === 'Enter' && !e.shiftKey) {
                  e.preventDefault();
                  handleSendMessage(e);
                }
              }}
              placeholder="Type your message..."
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={handleSendMessage}
              disabled={loading}
              className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2"
            >
              {loading ? 'Sending...' : <><Send size={18} /> Send</>}
            </button>
          </div>
        </div>
      )}

      {/* AI Document Chat Mode */}
      {chatMode === 'ai' && (
        <div className="space-y-4">
          {/* Document Upload Section */}
          <div className="border border-gray-200 rounded-lg p-4 bg-gray-50">
            <h3 className="text-sm font-semibold text-gray-800 mb-3 flex items-center gap-2">
              <Upload size={16} />
              Upload Project Documents
            </h3>

            <div className="space-y-3">
              <div className="border-2 border-dashed border-gray-300 rounded-lg p-3 text-center hover:border-blue-500 transition bg-white">
                <input
                  type="file"
                  onChange={handleFileChange}
                  className="hidden"
                  id="file-upload"
                  accept=".pdf,.txt,.doc,.docx"
                />
                <label 
                  htmlFor="file-upload" 
                  className="cursor-pointer flex flex-col items-center"
                >
                  <FileText size={24} className="text-gray-400 mb-1" />
                  {file ? (
                    <div className="flex items-center gap-2">
                      <div className="text-xs">
                        <p className="font-semibold text-blue-600">{file.name}</p>
                        <p className="text-gray-500">
                          {(file.size / 1024).toFixed(2)} KB
                        </p>
                      </div>
                      <button
                        onClick={(e) => {
                          e.preventDefault();
                          handleRemoveFile();
                        }}
                        className="text-red-500 hover:text-red-700"
                      >
                        <X size={16} />
                      </button>
                    </div>
                  ) : (
                    <p className="text-gray-500 text-xs">
                      Click to select a file (PDF, TXT, DOC, DOCX)
                    </p>
                  )}
                </label>
              </div>

              {error && (
                <div className="flex items-center gap-2 p-2 bg-red-50 border border-red-200 rounded text-red-700 text-xs">
                  <AlertCircle size={14} />
                  {error}
                </div>
              )}

              {uploadStatus && (
                <div className="p-2 bg-green-50 border border-green-200 rounded text-green-700 text-xs">
                  ✓ {uploadStatus}
                </div>
              )}

              <button
                onClick={handleUpload}
                disabled={!file || uploading}
                className="w-full py-2 bg-purple-600 text-white rounded hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed transition text-sm font-medium"
              >
                {uploading ? 'Uploading...' : 'Upload Document'}
              </button>
            </div>

            {/* Uploaded Documents List */}
            {uploadedDocuments.length > 0 && (
              <div className="mt-3 pt-3 border-t border-gray-200">
                <h4 className="text-xs font-semibold text-gray-700 mb-2">
                  Uploaded Documents ({uploadedDocuments.length})
                </h4>
                <div className="space-y-1">
                  {uploadedDocuments.map((doc) => (
                    <div 
                      key={doc.id} 
                      className="flex items-center justify-between p-2 bg-white rounded text-xs"
                    >
                      <div className="flex items-center gap-2">
                        <FileText size={14} className="text-purple-500" />
                        <span className="text-gray-700">{doc.name || doc.filename}</span>
                      </div>
                      <button
                        onClick={() => handleDeleteDocument(doc.id)}
                        className="text-red-500 hover:text-red-700"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* AI Chat Messages */}
          <div className="border border-gray-200 rounded-lg p-4">
            <div className="space-y-3 mb-3 max-h-80 overflow-y-auto bg-gray-50 rounded-lg p-3">
              {aiMessages.length === 0 ? (
                <div className="text-center text-gray-400 py-8 text-sm">
                  Upload a document and start asking questions...
                </div>
              ) : (
                aiMessages.map((msg, idx) => (
                  <div
                    key={idx}
                    className={`p-2 rounded-lg text-sm ${
                      msg.type === 'user'
                        ? 'bg-blue-50 ml-8'
                        : msg.type === 'ai'
                        ? 'bg-white mr-8 shadow-sm'
                        : msg.type === 'system'
                        ? 'bg-green-50 text-center'
                        : 'bg-red-50 text-center'
                    }`}
                  >
                    <div className="flex items-start gap-2">
                      {msg.type === 'user' && (
                        <div className="w-6 h-6 bg-blue-500 rounded-full flex items-center justify-center text-white text-xs font-semibold flex-shrink-0">
                          {msg.userName?.charAt(0).toUpperCase() || 'U'}
                        </div>
                      )}
                      {msg.type === 'ai' && (
                        <div className="w-6 h-6 bg-purple-500 rounded-full flex items-center justify-center text-white text-xs font-semibold flex-shrink-0">
                          AI
                        </div>
                      )}
                      <div className="flex-1">
                        <p className="text-gray-800 whitespace-pre-wrap">{msg.text}</p>
                        {msg.timestamp && (
                          <p className="text-xs text-gray-400 mt-1">
                            {new Date(msg.timestamp).toLocaleTimeString()}
                          </p>
                        )}
                      </div>
                    </div>
                  </div>
                ))
              )}
              {aiLoading && (
                <div className="bg-white mr-8 p-2 rounded-lg shadow-sm">
                  <div className="flex items-center gap-2">
                    <div className="w-6 h-6 bg-purple-500 rounded-full flex items-center justify-center text-white text-xs font-semibold">
                      AI
                    </div>
                    <div className="flex gap-1">
                      <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce"></div>
                      <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                      <div className="w-1.5 h-1.5 bg-gray-400 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                    </div>
                  </div>
                </div>
              )}
              <div ref={messagesEndRef} />
            </div>

            {/* AI Question Input */}
            <div className="flex gap-2">
              <input
                type="text"
                value={aiQuestion}
                onChange={(e) => setAiQuestion(e.target.value)}
                onKeyPress={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    handleAskAiQuestion();
                  }
                }}
                placeholder="Ask a question about the documents..."
                disabled={uploadedDocuments.length === 0 || aiLoading}
                className="flex-1 px-3 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-purple-500 disabled:bg-gray-100 text-sm"
              />
              <button
                onClick={handleAskAiQuestion}
                disabled={!aiQuestion.trim() || aiLoading || uploadedDocuments.length === 0}
                className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 disabled:opacity-50 disabled:cursor-not-allowed transition flex items-center gap-2"
              >
                <Send size={16} />
              </button>
            </div>

            {uploadedDocuments.length === 0 && (
              <p className="text-xs text-gray-500 mt-2 text-center">
                Upload a document first to start asking questions
              </p>
            )}
          </div>
        </div>
      )}

      {/* Delete Confirmation Modal */}
      {showDeleteConfirm && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg p-6 max-w-md w-full mx-4">
            <h3 className="text-xl font-bold text-gray-900 mb-2">
              Delete Chat History?
            </h3>
            <p className="text-gray-600 mb-6">
              Are you sure you want to delete all messages in this chat? This action cannot be undone.
            </p>
            <div className="flex gap-4">
              <button
                onClick={() => setShowDeleteConfirm(false)}
                disabled={deleting}
                className="flex-1 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                onClick={handleDeleteAllMessages}
                disabled={deleting}
                className="flex-1 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 disabled:opacity-50"
              >
                {deleting ? 'Deleting...' : 'Delete All'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatTab;
